package io.fireflysoftware.core.product.core.services.definition;

import static org.junit.jupiter.api.Assertions.*;
import io.fireflysoftware.core.product.models.repositories.definition.lifecycle.ProductDefinitionCommandPersistence;
import io.r2dbc.pool.*;
import io.r2dbc.spi.IsolationLevel;
import java.lang.reflect.*;
import java.time.*;
import java.util.function.Function;
import java.util.concurrent.*;
import io.r2dbc.spi.*;
import org.fireflyframework.core.transaction.*;
import org.junit.jupiter.api.Test;
import org.springframework.context.support.GenericApplicationContext;
import org.springframework.data.r2dbc.core.DefaultReactiveDataAccessStrategy;
import org.springframework.data.r2dbc.dialect.PostgresDialect;
import reactor.core.publisher.Mono;
import reactor.test.StepVerifier;

/** Real Spring lifecycle over networkless supplied driver publishers; no native/business acceptance. */
class TermPcPersistenceBoundaryTest {
    ConnectionPool pool(InsuranceQuotePurposeTransactionTest.Driver d){return new ConnectionPool(ConnectionPoolConfiguration.builder(d).initialSize(0).maxSize(1).build());}
    void awaitStage(CountDownLatch stage){try{assertTrue(stage.await(1,TimeUnit.SECONDS),"Expected driver stage was not entered before advancing virtual time");}catch(InterruptedException failure){Thread.currentThread().interrupt();throw new AssertionError(failure);}}
    ProductDefinitionCommandPersistence persistence(ConnectionPool p,GenericApplicationContext c,boolean bounded){try{return ProductDefinitionCommandPersistence.class.getConstructor(ConnectionPool.class,org.springframework.data.r2dbc.convert.R2dbcConverter.class,org.springframework.context.ApplicationContext.class,boolean.class).newInstance(p,new DefaultReactiveDataAccessStrategy(PostgresDialect.INSTANCE).getConverter(),c,bounded);}catch(InvocationTargetException e){if(e.getCause()instanceof RuntimeException r)throw r;throw new AssertionError(e.getCause());}catch(ReflectiveOperationException e){throw new AssertionError("Opt-in original mapped persistence boundary missing",e);}}
    @SuppressWarnings("unchecked") Mono<String> execute(ProductDefinitionCommandPersistence p,boolean readOnly,Function<RootTransactionScope,Mono<String>> work){return Mono.defer(()->{var clock=InsuranceQuotePurposeTransactionTest.clock();var ticks=InsuranceQuotePurposeTransactionTest.nanos();var budget=R2dbcOperationBudget.observed(clock.instant(),clock.instant().plusSeconds(1),ticks.getAsLong(),Duration.ofSeconds(1),clock,ticks);try{return (Mono<String>)p.getClass().getMethod("executeBounded",R2dbcOperationBudget.class,boolean.class,Function.class).invoke(p,budget,readOnly,work);}catch(InvocationTargetException e){if(e.getCause()instanceof RuntimeException r)throw r;throw new AssertionError(e.getCause());}catch(ReflectiveOperationException e){throw new AssertionError("Bounded original mapped execution missing",e);}});}
    @Test void originalConstructorKeepsOriginalFactoryWithoutOpeningConnection(){var d=new InsuranceQuotePurposeTransactionTest.Driver();var pool=pool(d);try(var c=new GenericApplicationContext()){c.refresh();var p=new ProductDefinitionCommandPersistence(pool,new DefaultReactiveDataAccessStrategy(PostgresDialect.INSTANCE).getConverter(),c);assertSame(pool,p.operations().getDatabaseClient().getConnectionFactory());assertSame(pool,p.transactionManager().getConnectionFactory());assertEquals(0,d.creates);p.close();}}
    @Test void optInGraphHasOneStableOwnedFactoryAcrossMappedTemplateAndManager(){var d=new InsuranceQuotePurposeTransactionTest.Driver();var pool=pool(d);try(var c=new GenericApplicationContext()){c.refresh();var p=persistence(pool,c,true);var factory=p.operations().getDatabaseClient().getConnectionFactory();assertEquals(OwnedLeaseConnectionFactory.class,factory.getClass());assertSame(factory,p.transactionManager().getConnectionFactory());assertEquals(0,d.creates);}finally{pool.disposeLater().block(Duration.ofSeconds(1));}}
    @Test void optInWriteBoundaryUsesReadCommittedAndReleasesBorrowedHandleBeforeEmission(){var d=new InsuranceQuotePurposeTransactionTest.Driver();var pool=pool(d);try(var c=new GenericApplicationContext()){c.refresh();var p=persistence(pool,c,true);StepVerifier.withVirtualTime(()->execute(p,false,s->Mono.just("protected"))).assertNext(x->{assertEquals("protected",x);assertEquals(1,d.commits);assertFalse(d.readOnlyIntent);assertEquals(IsolationLevel.READ_COMMITTED,d.isolationIntent);assertEquals(0,pool.getMetrics().orElseThrow().acquiredSize());}).verifyComplete();}finally{pool.disposeLater().block(Duration.ofSeconds(1));}}
    @Test void optInBeginStallCannotKeepItsBorrowedHandle(){var d=new InsuranceQuotePurposeTransactionTest.Driver();d.stallBegin=true;d.expectedContextMarker="owned-pooled-marker";var started=d.beginReady;var pool=pool(d);try(var c=new GenericApplicationContext()){c.refresh();var p=persistence(pool,c,true);StepVerifier.withVirtualTime(()->execute(p,false,s->Mono.just("protected")).contextWrite(context->context.put("owned-fixture-marker","owned-pooled-marker"))).then(()->awaitStage(started)).thenAwait(Duration.ofSeconds(5)).expectErrorSatisfies(e->{assertInstanceOf(RootTransactionException.class,e);assertEquals(RootTransactionException.Stage.BEGIN,((RootTransactionException)e).stage());}).verify(Duration.ofSeconds(1));assertEquals(1,d.beginCancelled);assertTrue(d.contextMarkerRetained.get());assertEquals(0,pool.getMetrics().orElseThrow().acquiredSize());assertEquals(0,d.commits);}finally{pool.disposeLater().block(Duration.ofSeconds(1));}}
    @Test void optInCommitStallCannotEmitProtectedResult(){var d=new InsuranceQuotePurposeTransactionTest.Driver();d.stallCommit=true;d.expectedContextMarker="owned-pooled-marker";var started=d.commitReady;var pool=pool(d);try(var c=new GenericApplicationContext()){c.refresh();var p=persistence(pool,c,true);StepVerifier.withVirtualTime(()->execute(p,false,s->Mono.just("protected")).contextWrite(context->context.put("owned-fixture-marker","owned-pooled-marker"))).then(()->awaitStage(started)).thenAwait(Duration.ofSeconds(6)).expectErrorSatisfies(e->{assertInstanceOf(RootTransactionException.class,e);assertEquals(RootTransactionException.Stage.COMMIT,((RootTransactionException)e).stage());}).verify(Duration.ofSeconds(1));assertEquals(1,d.commitCancelled);assertTrue(d.contextMarkerRetained.get());assertEquals(0,pool.getMetrics().orElseThrow().acquiredSize());}finally{pool.disposeLater().block(Duration.ofSeconds(1));}}
    @Test void optInReadBoundaryIsPhysicalReadonlyRepeatableRead(){var d=new InsuranceQuotePurposeTransactionTest.Driver();var pool=pool(d);try(var c=new GenericApplicationContext()){c.refresh();var p=persistence(pool,c,true);StepVerifier.withVirtualTime(()->execute(p,true,scope->Mono.just("protected"))).assertNext(value->{assertTrue(d.readOnlyIntent);assertEquals(IsolationLevel.REPEATABLE_READ,d.isolationIntent);assertEquals(0,pool.getMetrics().orElseThrow().acquiredSize());}).verifyComplete();}finally{pool.disposeLater().block(Duration.ofSeconds(1));}}

}
